-- ================================================================
-- schema.sql -- Omada captive portal database schema
-- ================================================================
-- Target: SQLite (development) / PostgreSQL (production)
--
-- This file is written in SQLite syntax (AUTOINCREMENT).
-- The db/client.js layer's convertSchema() function translates
-- AUTOINCREMENT to GENERATED BY DEFAULT AS IDENTITY at runtime
-- when running against PostgreSQL.
-- The db/client.js layer also handles placeholder conversion (? -> $N).
--
-- Run with: node src/db/migrate.js
-- ================================================================

-- Voucher codes table
CREATE TABLE IF NOT EXISTS vouchers (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    code            VARCHAR(32) NOT NULL UNIQUE,
    type            VARCHAR(16) NOT NULL DEFAULT 'standard', -- 'standard' | 'premium'
    duration_minutes INTEGER NOT NULL DEFAULT 60,
    price           INTEGER, -- fixed price in centavos; NULL = use dynamic pricing
    down_kbps       INTEGER, -- per-voucher download cap in Kbps; NULL = tier/default caps
    up_kbps         INTEGER, -- per-voucher upload cap in Kbps; NULL = tier/default caps
    state           VARCHAR(16) NOT NULL DEFAULT 'active', -- 'active' | 'reserved' | 'claimed' | 'used' | 'expired'
    assigned_ref_no VARCHAR(64), -- full payment ref_no this voucher was claimed for; NULL = unclaimed (see migrate_add_voucher_ref.js)
    used_by_mac     VARCHAR(32),
    used_at         TIMESTAMP,
    created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    expires_at      TIMESTAMP
);

-- Sessions table
CREATE TABLE IF NOT EXISTS sessions (
        id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id          VARCHAR(32) NOT NULL UNIQUE,
    client_mac          VARCHAR(32) NOT NULL,
    ref_no              VARCHAR(64) UNIQUE,
    client_ip           VARCHAR(45),
    ap_mac              VARCHAR(32),
    ssid_name           VARCHAR(64),
    duration_minutes    INTEGER NOT NULL DEFAULT 60,
    voucher_type        VARCHAR(16) NOT NULL DEFAULT 'standard', -- 'standard' | 'premium'
    -- Bandwidth snapshot taken from the voucher at authorization time, in Kbps.
    -- Kept on the session so a re-authorization / resume re-applies exactly the
    -- cap the guest paid for, even if the voucher row changes afterwards.
    down_kbps           INTEGER,
    up_kbps             INTEGER,
    total_duration_seconds INTEGER, -- preserves original duration for premium remaining-time tracking
    started_at          TIMESTAMP,
    expires_at          TIMESTAMP,
    -- Premium only: the ABSOLUTE deadline of the pass, counted from creation
    -- and never extended by a pause or a resume (config: PREMIUM_HARD_EXPIRY_HOURS,
    -- 168 h = 7 days). Once it passes the session is void even with frozen time
    -- left. NULL for Standard sessions, which never hard-expire.
    absolute_expires_at TIMESTAMP,
    paused_at           TIMESTAMP,
    remaining_seconds   INTEGER,
    state               VARCHAR(16) NOT NULL DEFAULT 'pending',
    voucher_used        VARCHAR(32),
    provider_session_id VARCHAR(128),
    payment_event_id    VARCHAR(128),
    payment_amount      INTEGER,
    payment_method      VARCHAR(32),
    omada_auth_failed   BOOLEAN DEFAULT FALSE,
    expire_reason       VARCHAR(32),
    expired_at          TIMESTAMP,
    created_at          TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Webhook events table
CREATE TABLE IF NOT EXISTS webhook_events (
        id           INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id     VARCHAR(128) NOT NULL UNIQUE,
    ref_no       VARCHAR(64) UNIQUE,
    session_id   VARCHAR(32),
        provider     VARCHAR(16),
    event_type   VARCHAR(64),
    amount       INTEGER,
    mobile_number VARCHAR(15), -- 11-digit PH mobile (09XXXXXXXXX) captured at claim time; the SMS destination
    status       VARCHAR(16),
    processed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- ================================================================
-- Pending payment verification (MacroDroid screen-scraping)
-- ================================================================
-- Written by POST /api/payment/claim when the 4 digits the customer typed do
-- not match any recorded webhook_events row. The row holds everything needed to
-- finish the claim once the Android handset has read the receipt: the device to
-- authorize, the number to text, the tier the customer asked for, and the
-- reference digits.
--
-- state:
--   pending  — MacroDroid has been asked to look at the e-wallet screen
--   verified — it found the payment; ref_no + amount were filled in and an
--              'unclaimed' webhook_events row now carries that payment
--   failed   — it could not find/confirm the payment (see failure_reason)
--   expired  — no answer within PENDING_CLAIM_TTL_MS (config/index.js)
--   claimed  — the verified claim has since produced a voucher
CREATE TABLE IF NOT EXISTS pending_claims (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    claim_id        VARCHAR(32) NOT NULL UNIQUE, -- 'clm_…' returned to the portal
    ref_suffix      VARCHAR(4) NOT NULL,         -- last 4 digits the customer typed
    client_mac      VARCHAR(32),                 -- NULL when the device is unknown
    mobile_number   VARCHAR(15) NOT NULL,        -- SMS destination once claimed
    requested_tier  VARCHAR(16),                 -- 'standard' | 'premium' | NULL
    state           VARCHAR(16) NOT NULL DEFAULT 'pending',
    ref_no          VARCHAR(64),                 -- full reference, filled in by MacroDroid
    amount          INTEGER,                     -- pesos, exactly as scraped
    failure_reason  VARCHAR(255),
    created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    expires_at      TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_pending_claims_claim_id ON pending_claims(claim_id);
CREATE INDEX IF NOT EXISTS idx_pending_claims_lookup   ON pending_claims(ref_suffix, state);

-- ----------------------------------------------------------------
-- claim_attempts — per-suffix failed-claim budget
--
-- POST /api/payment/claim takes the last 4 digits of a reference, so its
-- 10,000-value space has to be budgeted independently of the caller's IP
-- address (which is spoofable via X-Forwarded-For). One row per suffix; a
-- successful claim deletes it, and the row stops locking once its window has
-- elapsed. See services/claim-attempts.js.
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS claim_attempts (
    ref_suffix        VARCHAR(8) NOT NULL PRIMARY KEY,
    failed_count      INTEGER NOT NULL DEFAULT 0,
    window_started_at TIMESTAMP,
    last_attempt_at   TIMESTAMP,
    last_client_ip    VARCHAR(45)          -- diagnostics only; never the key
);

-- ----------------------------------------------------------------
-- ref_no duplicate protection
-- Payment reference numbers are unique per transaction. SQLite
-- enforces this via the UNIQUE column constraint in each CREATE
-- TABLE above; PostgreSQL enforces it via the partial unique
-- indexes below (which also cover fresh production databases).
--
-- NOTE: these indexes reference ref_no, which does not exist on
-- legacy databases. migrate.js therefore runs column reconciliation
-- (migrate_fix.js) BEFORE applying this file, so the columns always
-- exist by the time these statements run.
-- ----------------------------------------------------------------
CREATE UNIQUE INDEX IF NOT EXISTS idx_sessions_ref_no ON sessions(ref_no) WHERE ref_no IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_webhook_events_ref_no ON webhook_events(ref_no) WHERE ref_no IS NOT NULL;

-- Indexes
CREATE INDEX IF NOT EXISTS idx_sessions_state      ON sessions(state);
CREATE INDEX IF NOT EXISTS idx_sessions_client_mac ON sessions(client_mac);
CREATE INDEX IF NOT EXISTS idx_sessions_expires_at ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_sessions_session_id ON sessions(session_id);
CREATE INDEX IF NOT EXISTS idx_vouchers_code       ON vouchers(code);
CREATE INDEX IF NOT EXISTS idx_sessions_provider   ON sessions(provider_session_id);

-- Admin users
CREATE TABLE IF NOT EXISTS admin_users (
        id            INTEGER PRIMARY KEY AUTOINCREMENT,
    username      VARCHAR(64) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    role          VARCHAR(16) DEFAULT 'admin',
    created_at    TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    last_login    TIMESTAMP
);

-- ================================================================
-- Portal client context
-- ================================================================
-- Controller context (AP MAC / SSID / radio ID) captured when a client
-- lands on the captive portal page, keyed by client MAC. The payment
-- webhook reads this row to authorize the client via extPortal/auth.
--
-- ASSUMPTION (single-site deployment): the lookup key is client_mac
-- alone. The `site` column records the site at capture time for future
-- collision detection only — see migrate_add_portal_context.js.
--
-- Staleness: rows older than PORTAL_CONTEXT_MAX_AGE_MS (config/index.js,
-- 1 hour) are treated as MISSING by the webhook (fail-loud
-- MISSING_PORTAL_CONTEXT path). seen_at is refreshed on every portal
-- page load by the landing beacon.
CREATE TABLE IF NOT EXISTS portal_client_context (
    client_mac  VARCHAR(32) PRIMARY KEY,
    client_ip   VARCHAR(45),
    ap_mac      VARCHAR(32) NOT NULL,
    ssid_name   VARCHAR(64) NOT NULL,
    radio_id    INTEGER NOT NULL DEFAULT 0,
    site        VARCHAR(64) NOT NULL DEFAULT 'Default',
    seen_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- ================================================================
-- Payment method availability (admin toggle)
-- ================================================================
-- One row per payment method the captive portal can offer (the GCash, Maya
-- and QR Ph e-wallets plus cash). The receiver details and QR images stay in
-- the environment (GCASH_* / MAYA_* / QRPH_* — see routes/payment.js); this
-- table only owns the on/off state so an admin can disable a method without a
-- redeploy. Cash has no receiver details: it authorizes via voucher claimed at
-- the counter, but its tile is toggled and branded like the others.
--
-- Read by GET /api/payment/methods (public, captive portal) and by the admin
-- routes GET/PUT /api/admin/payment-methods. A method with NO row is treated
-- as ENABLED, so a database created before this table existed keeps every
-- payment option working.
--
-- The seed below is idempotent and never overwrites an admin's choice: a row
-- that already exists is left untouched, so re-running `npm run db:migrate`
-- after toggling a method off does NOT turn it back on.
CREATE TABLE IF NOT EXISTS payment_methods (
    method_key   VARCHAR(32) PRIMARY KEY, -- 'gcash' | 'maya' | 'qrph' | 'cash'
    display_name VARCHAR(64) NOT NULL,
    is_active    BOOLEAN NOT NULL DEFAULT TRUE, -- SQLite stores 1/0; PostgreSQL stores true/false
    -- Admin-uploaded logo as a complete data URI (data:image/png;base64,…).
    -- NULL = use the bundled asset (assets/images/<method>.png). Written by
    -- PUT /api/admin/payment-methods/:key and served to the portal as
    -- logoBase64 on GET /api/payment/methods.
    logo_base64  TEXT,
    updated_at   TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO payment_methods (method_key, display_name, is_active) VALUES
    ('gcash', 'GCash', TRUE),
    ('maya',  'Maya',  TRUE),
    ('qrph',  'QR Ph', TRUE),
    ('cash',  'Cash',  TRUE)
ON CONFLICT (method_key) DO NOTHING;

-- ================================================================
-- Application settings (key/value)
-- ================================================================
-- Small persistent store for admin-controlled baselines. The only key in use
-- is 'stats_reset_at': DELETE /api/admin/transactions records the instant of
-- the last dashboard reset here, and GET /api/admin/stats reports session and
-- revenue cards only for rows created at/after it. Stored as the database's
-- UTC CURRENT_TIMESTAMP text so it compares directly with sessions.created_at.
CREATE TABLE IF NOT EXISTS app_settings (
    setting_key   VARCHAR(64) PRIMARY KEY,
    setting_value TEXT,
    updated_at    TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- ================================================================
-- Notes:
--
-- 1. MAC addresses stored with colons (e.g. aa:bb:cc:dd:ee:ff).
--    Normalize on insert via normalizeMac().
--
-- 2. All timestamps are in UTC. Display in local time at frontend.
--
-- 3. Consider adding a batch table for bulk voucher generation,
--    or integrate directly with your point-of-sale / PMS system.
-- ================================================================
